#!/bin/sh
#
# Xcode Cloud runs this right after cloning, before it looks for the project.
#
# BallotWatch.xcodeproj is generated by XcodeGen from project.yml and is not
# committed, so without this step every Xcode Cloud build fails with
# "Project BallotWatch.xcodeproj does not exist at ios/BallotWatch.xcodeproj".
#
# Secrets.plist is gitignored too. Set SUPABASE_URL and SUPABASE_ANON_KEY as
# environment variables on the Xcode Cloud workflow and it is written here.
# A plain build passes without them; an archive does not, because an app
# without Secrets.plist stops at launch.
#
set -eu

IOS_DIR="$(cd "$(dirname "$0")/.." && pwd)"
cd "$IOS_DIR"

if ! command -v xcodegen >/dev/null 2>&1; then
  HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_NO_INSTALL_CLEANUP=1 brew install xcodegen
fi

SECRETS="BallotWatch/Secrets.plist"
if [ -n "${SUPABASE_URL:-}" ] && [ -n "${SUPABASE_ANON_KEY:-}" ]; then
  cat > "$SECRETS" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>SUPABASE_URL</key>
	<string>${SUPABASE_URL}</string>
	<key>SUPABASE_ANON_KEY</key>
	<string>${SUPABASE_ANON_KEY}</string>
</dict>
</plist>
PLIST
  echo "Wrote $SECRETS from the workflow's environment variables."
elif [ "${CI_XCODEBUILD_ACTION:-}" = "archive" ]; then
  echo "error: SUPABASE_URL and SUPABASE_ANON_KEY are not set on this workflow." >&2
  echo "An archive without Secrets.plist would stop at launch. Add both under" >&2
  echo "the workflow's Environment Variables in Xcode Cloud." >&2
  exit 1
else
  echo "warning: SUPABASE_URL / SUPABASE_ANON_KEY are not set; building without Secrets.plist."
fi

xcodegen generate
